import pytesseract
from PIL import Image, ImageFilter, ImageEnhance
import re
import os
import openpyxl

IMG_DIR = "/app/workspace/dataset/img"
OUTPUT_FILE = "/app/workspace/stat_ocr.xlsx"

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
    "TAX", "GST", "SST",
    "DISCOUNT",
    "CHANGE",
    "CASH TENDERED",
    "SAVING",
    "ITEM COUNT",
    "ITEM QTY",
    "ITEMS",
    "QTY",
]

SKIP_PATTERNS = [
    "TOTAL INCLUDES",
    "TOTAL SAVINGS",
    "TOTAL ITEM",
    "TOTAL QTY",
    "TOTAL QUANTITY",
    "ITEM TOTAL",
    "INCLUDING GST",
    "INCL GST",
    "INCL. GST",
    "EXCL GST",
    "EXCL. GST",
    "EXCLUDING GST",
    "EXCLUSIVE GST",
    "EXCLUSIVE OF GST",
    "EXCLUDING",
    "EXCLUSIVE",
    "TAX INVOICE",
    "TAX TOTALS",
    "AMOUNT TAX",
    "AMOUNT(RM) TAX",
    "GST SUMMARY AMOUNT",
    "DESCRIPTION AMOUNT",
    "DESCRIPTION",
    "PRICE AMOUNT",
    "TAX SUMMARY",
    "QTY ITEM TOTAL",
    "CASH TENDERED",
    "INCLUDED IN TOTAL",
]


def ocr_image(filepath):
    """Run OCR with multiple preprocessing and PSM modes."""
    img = Image.open(filepath)
    texts = []

    # Default OCR (psm=3)
    texts.append(pytesseract.image_to_string(img))

    # Enhanced OCR: grayscale + contrast + sharpen with psm=6
    gray = img.convert('L')
    enhancer = ImageEnhance.Contrast(gray)
    enhanced = enhancer.enhance(2.0)
    sharpened = enhanced.filter(ImageFilter.SHARPEN)
    texts.append(pytesseract.image_to_string(sharpened, config='--psm 6'))

    # Additional: original image with psm=4 (assume single column)
    texts.append(pytesseract.image_to_string(img, config='--psm 4'))

    # Additional: original image with psm=6
    texts.append(pytesseract.image_to_string(img, config='--psm 6'))

    return texts


def extract_date(text):
    """Extract date from receipt text and return in ISO format YYYY-MM-DD."""
    lines = text.split('\n')

    # First look for lines with Date keyword
    date_lines = []
    for line in lines:
        if re.search(r'\bdate\b', line, re.IGNORECASE):
            date_lines.append(line)

    search_order = date_lines + lines

    patterns = [
        (r'(\d{1,2})[/\-](\d{1,2})[/\-](20\d{2})', 'dmy4'),
        (r'(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b', 'dmy2'),
    ]

    for line in search_order:
        for pattern, fmt in patterns:
            matches = re.findall(pattern, line)
            for match in matches:
                try:
                    if fmt == 'dmy4':
                        day, month, year = int(match[0]), int(match[1]), int(match[2])
                    elif fmt == 'dmy2':
                        day, month, year = int(match[0]), int(match[1]), int(match[2])
                        year += 2000

                    if 1 <= month <= 12 and 1 <= day <= 31 and 2010 <= year <= 2025:
                        return f"{year:04d}-{month:02d}-{day:02d}"
                except (ValueError, IndexError):
                    continue

    return None


def should_skip_line(line):
    """Check if a line should be skipped."""
    upper = line.upper().strip()
    for pat in SKIP_PATTERNS:
        if pat in upper:
            return True
    for kw in EXCLUSION_KEYWORDS:
        if kw in upper:
            return True
    return False


def extract_amounts_from_text(text):
    """Extract all monetary amounts from text."""
    matches = re.findall(r'[\d,]+\.\d{2}\b', text)
    return [m.replace(',', '') for m in matches]


def extract_total_amount(text):
    """Extract total amount from receipt text using keyword priority."""
    lines = text.split('\n')

    # Priority 1: GRAND TOTAL
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if 'GRAND TOTAL' in upper:
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                amounts = extract_amounts_from_text(lines[i + 1])
                if amounts:
                    return amounts[-1]

    # Priority 2: TOTAL RM (standalone total with RM)
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if should_skip_line(line):
            continue
        if re.search(r'\bTOTAL\s*:?\s*RM\b', upper) or 'TOTAL(RM)' in upper:
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                amounts = extract_amounts_from_text(lines[i + 1])
                if amounts:
                    return amounts[-1]

    # Priority 3: TOTAL AMOUNT
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if should_skip_line(line):
            continue
        if 'TOTAL AMOUNT' in upper:
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                amounts = extract_amounts_from_text(lines[i + 1])
                if amounts:
                    return amounts[-1]

    # Priority 4a: Total Rounded / Rounded Total / Total After Adj / Total After Rounding
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if any(kw in upper for kw in ['TOTAL ROUNDED', 'TOTAL AFTER', 'ROUNDED TOTAL']):
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                amounts = extract_amounts_from_text(lines[i + 1])
                if amounts:
                    return amounts[-1]

    # Priority 4b: Net Total / Nett Total
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if 'NET TOTAL' in upper or 'NETT TOTAL' in upper:
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                amounts = extract_amounts_from_text(lines[i + 1])
                if amounts:
                    return amounts[-1]

    # Priority 4c: Total Inclusive / Total Incl (but not "Total Includes")
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if 'TOTAL' in upper and ('INCLUSIVE' in upper or 'INCL' in upper):
            if 'INCLUDES' in upper:
                continue
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                amounts = extract_amounts_from_text(lines[i + 1])
                if amounts:
                    return amounts[-1]

    # Priority 4d: TOTAL DUE / AMOUNT DUE / BALANCE DUE
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if any(kw in upper for kw in ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE']):
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                amounts = extract_amounts_from_text(lines[i + 1])
                if amounts:
                    return amounts[-1]

    # Priority 4e: Total Sales (not excluded)
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if 'TOTAL SALES' in upper:
            if should_skip_line(line):
                continue
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                amounts = extract_amounts_from_text(lines[i + 1])
                if amounts:
                    return amounts[-1]

    # Priority 4f: Standalone TOTAL
    for i, line in enumerate(lines):
        upper = line.upper().strip()
        if should_skip_line(line):
            continue
        if re.search(r'\bTOTAL\b', upper):
            amounts = extract_amounts_from_text(line)
            if amounts:
                return amounts[-1]
            if i + 1 < len(lines):
                next_line = lines[i + 1].strip()
                if next_line and not should_skip_line(next_line):
                    amounts = extract_amounts_from_text(next_line)
                    if amounts:
                        return amounts[-1]

    return None


def process_receipt(filepath, filename):
    """Process a single receipt image."""
    texts = ocr_image(filepath)

    # Try to extract date from all OCR results
    date = None
    for text in texts:
        date = extract_date(text)
        if date:
            break

    # Try to extract total from all OCR results
    total = None
    for text in texts:
        total = extract_total_amount(text)
        if total:
            break

    return date, total


def main():
    files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png'))])

    results = []
    for filename in files:
        filepath = os.path.join(IMG_DIR, filename)
        date, total = process_receipt(filepath, filename)
        results.append((filename, date, total))
        print(f"{filename}: date={date}, total={total}")

    # Write to Excel
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"

    ws.append(["filename", "date", "total_amount"])

    for filename, date, total in results:
        ws.append([filename, date, total])

    wb.save(OUTPUT_FILE)
    print(f"\nSaved to {OUTPUT_FILE}")


if __name__ == "__main__":
    main()

